definition.raw:
we define a $H(\d,K;  {\mathbb S})$ bubble function space
\an{\lab{bh}  \Sigma_{K, k,  b}: = \sum\limits_{0\leq i<j\leq n} \lambda_i\lambda_jP_{k-2}(K;  \mathbb{R})T_{i, j}}
Define the full $H(\d,K;  {\mathbb S})$ bubble function space consisting of polynomials of degree $\leq k$
\begin{equation}
\Sigma_{\partial K,  k, 0}:=\{\tau\in H(\d, K;  \mathbb{S})\cap P_{k}(K; \mathbb{S}), \tau\b \nu|_{\partial K}=0 \}.

define the following enriched $P_2(K;  \mathbb{S})$ space
  \begin{equation}
  P_2^\ast(K; \mathbb{S}):=P_2(K; \mathbb{S})+\Sigma_{3\rightarrow n+1, DF}(K; \mathbb{S}).

we define
  \begin{equation}
    M_2(K):=\{\tau\in P_2^\ast(K;  \mathbb{S}), \d\tau=0 \text{ and }\tau\nu|_{\partial K}=0 \},
  \end{equation}
  where $\nu$ is the   normal vector of $\partial K$.

we define
\begin{equation}\label{Shplus}
\Sigma_{2,h}^\ast:=\{\tau\in H(\d, \Omega; \mathbb{S}), \tau|_K\in P_2^\ast(K; \mathbb{S}) \text{ for  any }K\in\mathcal{T}_h\}.

we define
  \begin{equation}
    M_k(K):=\{\tau\in P_k^\ast(K;  \mathbb{S}), \d\tau=0 \text{ and }\tau\nu|_{\partial K}=0 \},
  \end{equation}
  where $\nu$ is the   normal vector of $\partial K$.

we define
\begin{equation}\label{Shplushorder}
\Sigma_{k,h}^\ast:=\{\tau\in H(\d, \Omega; \mathbb{S}), \tau|_K\in P_k^\ast(K; \mathbb{S}) \text{ for  any }K\in\mathcal{T}_h\}.

Define
\begin{equation}
\begin{split}
 \mathbb{B}_F^1:=&\bigg\{\tau\in \Sigma_{2,h}^\ast, \tau=0 \text{ on }\Omega\backslash\omega_F, \int_F \tau\nu\cdot p ds=0 \text{ for any } p\in \big(R(\omega_F)|_F\big)^\perp,\\
 & \text{ the averages of }\tau \text{ over both } K^- \text{ and } K^+ \text{ vanish },\\
 & \text{ the values of } \int_K\tau:\theta d\b x \text{ vanish for any }\theta\in M_2(K), K=K^- \text{ and } K^+ \bigg\}.

we define the following enriched stress space
 \begin{equation}
   \Sigma_{k, h}^+=\Sigma_{k, h}+\sum\limits_{F} \mathbb{B}_F^1 \text{ for }2\leq k\leq n-1;
 \end{equation}
 and
 \begin{equation}
  \lab{Sh-plus}
   \Sigma_{k, h}^+=\Sigma_{k, h}+\sum\limits_{F} \mathbb{B}_F^2 \text{ for }k=n.

we define
 \begin{equation}
 \Sigma_{1,h}:=\{\tau\in H^1(\Omega;  \mathbb{S}), \tau|_K\in P_1(K, \mathbb{S})\text{ for any }K\in\mathcal{T}_h\}.

Define
\begin{equation}
\begin{split}
 \hat{\mathbb{B}}_F:=&\bigg\{\tau\in \hat{\Sigma}_{2,h}^\ast, \tau=0 \text{ on }\Omega\backslash\omega_F, \int_F \tau\nu\cdot p ds=0 \text{ for any } p\in \big(R(\omega_F)|_F\big)^\perp,\\
 & \text{ the values of } \int_K\tau:\theta d\b x \text{ vanish for any }\theta\in M_2(K), K=K^- \text{ and } K^+ \bigg\}.

Define $T^\perp_{j, F}, j=1, 2, 3$  such that
 \begin{equation}
 T_{i,F}:T_{j, F}^\perp=0,  T^\perp_{j, F}:T^\perp_{l, F}=\delta_{jl},  i, j, l=1, 2, 3.

Define the basis $v_{i,F}^\perp$, $i=1, 2, 3$,  of the orthogonal complement space of the restriction  of the rigid motion space on the face $F$ with respect to $P_1(F, \mathbb{R}^3)$, such that
 \begin{equation}
 \int_F v_{i,F}^\perp\cdot v_{j, F}ds=0, i=1,2,3, j=1,\cdots, 6.

theorem.raw:
\label{theorem3.1} A  matrix field  $\tau\in P_2^\ast(K; \mathbb{S})$ can be uniquely determined by the following degrees of
 freedom:
\begin{enumerate}
 \item For each $\ell$ dimensional simplex $\triangle_\ell$ of $K$, $0\leq \ell\leq n-1$,  with $\ell$ linearly independent tangential vectors $\b t_1, \cdots, \b t_\ell$, and $n-\ell$ linearly  independent normal vectors $\b \nu_1, \cdots, \b \nu_{n-\ell}$, the mean moments of degree at most $n-\ell$ over $\triangle_\ell$, of~~ $\b t_l^T\tau \b \nu_i$, $\b \nu_i^T\tau\b \nu_j$, $l=1, \cdots, \ell$, $i,j=1, \cdots, n-\ell$,  $\big( C_{n+1-\ell}^2+\ell (n-\ell)\big) C_{n}^\ell=\frac{(n-\ell)(n+\ell+1)}{2}C_{n}^\ell$ degrees of freedom  for each $\triangle_\ell$;
 \item the average of $\tau$ over $K$,  $\frac{n(n+1)}{2}$  degrees of freedom;
 \item the values of moments $\int_K \tau:\theta d\b x $, $\theta \in M_2(K)$, $\frac{(2n-1)!}{n!(n-1)!}\frac{n(n+1)}{2}+\frac{n(n+1)}{2}-n\frac{(2n)!}{n!n!}$ degrees of freedom.
 \end{enumerate}

A  matrix field  $\tau\in P_k^\ast(K; \mathbb{S})$ can be uniquely determined by the following degrees of
 freedom:
\begin{enumerate}
 \item For each $\ell$ dimensional simplex $\triangle_\ell$ of $K$, $0\leq \ell\leq n-1$,  with $\ell$ linearly independent tangential vectors $\b t_1, \cdots, \b t_\ell$, and $n-\ell$ linearly  independent normal vectors $\b \nu_1, \cdots, \b \nu_{n-\ell}$, the mean moments of degree at most $k+n-\ell-2$ over $\triangle_\ell$, of~~ $\b t_l^T\tau \b \nu_i$, $\b \nu_i^T\tau\b \nu_j$, $l=1, \cdots, \ell$, $i,j=1, \cdots, n-\ell$,  $\big( C_{n+1-\ell}^2+\ell (n-\ell)\big) C_{k+n-2}^\ell=\frac{(n-\ell)(n+\ell+1)}{2}C_{k+n-2}^\ell$ degrees of freedom  for each $\triangle_\ell$;
 \item the values $\int_K \tau: \theta d\b x$ for any $\theta \in \epsilon(P_{k-1}(K;  \mathbb{R}^n))$, $nC_{n+k-1}^n-\frac{n(n+1)}{2}$ degrees of freedom;
 \item the values $\int_K \tau: \theta d\b x$ for any $\theta \in M_k(K)$,  $\frac{(k+2n-3)!}{n!(k+n-3)!}\frac{n(n+1)}{2}+\frac{n(n+1)}{2}-n\frac{(k+2n-2)!}{n!(k+n-2)!}$ degrees of freedom
 \end{enumerate}

\label{MainError} Let
  $(\sigma, u)\in\Sigma\times V$ be the exact solution of
   problem \meqref{eqn1} and $(\tau_h, u_h)\in\Sigma_{k,h}^+\times
   V_{k,h}$ the finite element solution of \meqref{DP}.  Then,
   for $2\leq k\leq n$,
\an{ \lab{t1} \|\sigma-\sigma_h\|_{H({\rm div})}
    + \|u-u_h\|_{0}&\le     Ch^k(\|\sigma\|_{k+1}+\|u\|_{k}).
      }

\label{MainError2} Let
  $(\sigma, u)\in\Sigma\times V$ be the exact solution of
   problem \meqref{eqn1} and $(\tau_h, u_h)\in\hat{\Sigma}_{1,h}^+\times
   V_{1,h}$ the finite element solution of \meqref{DP2}.  Then,
\an{ \lab{t2} \|\sigma-\sigma_h\|_{H({\rm div})}
    + \|u-u_h\|_{0}&\le     Ch(\|\d \sigma\|_{1}+\|u\|_{1}),
      }
and
\begin{equation}
\|\sigma-\sigma_h\|_0\leq Ch^2\|\sigma\|_2.
\end{equation}

lemma.raw:
\lab{lemma2.1}
   The $\frac{(n+1)n}{2}$ symmetric tensors $T_{i,j}$ in \meqref{Tnew} are linearly independent, and
    form a basis of $\mathbb{S}$.

\label{lemma2.2}  It holds that
   \begin{equation}
   \Sigma_{K, k, b}=\Sigma_{\partial K,  k, 0}.
   \end{equation}

\label{lemma2.3} For any $K\in\mathcal{T}_h$, it holds that
\begin{equation}
\d \Sigma_{K, k, b}=R^\perp(K).
\end{equation}

\label{lemma2.4} It holds the following  Chu-Vandermonde combinatorial identity and its variant
\begin{equation}\label{van}
\sum\limits_{\ell=0}^nC_{n+1}^{\ell+1}C_{k-1}^\ell =\sum\limits_{\ell=0}^nC_{n+1}^{n-\ell}C_{k-1}^\ell=C_{n+k}^n,
\end{equation}
and
\begin{equation}\label{varvan}
\sum\limits_{\ell=0}^nC_{n+1}^{\ell+1}C_{k-1}^\ell C_{\ell+1}^2=\frac{(n+1)n}{2}C_{n+k-2}^n,
\end{equation}
where the combinatorial number $C_{n}^m=\frac{n\cdots (n-m+1)}{m\cdots 1}$ for $n\geq m$ and $C_{n}^m=0$ for $n<m$.

\label{lemma1}
For any $v_h\in V_{k,h}$,  there is a $\tau_h \in
    \widetilde \Sigma_{k,h}+\sum\limits_{F}\mathbb{B}_F^1$  with $2\leq k\leq n-1$ such that,
  for all polynomial $p\in R(K)$, $K\in\mathcal{T}_h$,
   \begin{equation}\label{l-1}  \int_K (\d\tau_h-v_h) \cdot p\, d\b x=0
      \quad \hbox{\rm
      and } \quad \|\tau_h\|_{H(\d)}\leq C\|v_h\|_{0}. \end{equation}

proof.raw:
The dimension of the space $\Sigma_{K, n+1, b}$ reads
  \begin{equation}
  \frac{(2n-1)!}{n!(n-1)!}\frac{n(n+1)}{2}.
  \end{equation}
  Since the dimension of $R(K)$ is $\frac{n(n+1)}{2}$, the dimension of $R^\perp(K)$ (with respect to $P_{n}(K, \mathbb{R}^n)$) is
  \begin{equation}
  n\frac{(2n)!}{n!n!}-\frac{n(n+1)}{2}.
  \end{equation}
  It follows from the definition of $P_2^\ast(K; \mathbb{S})$ and Lemma \ref{lemma2.2} that $M_2(K)$ contains all divergence free  tensor-value functions of  $\Sigma_{K, n+1, b}$. Then the desired result follows from Lemma \ref{lemma2.3}.

The dimension of the space $\Sigma_{K, k+n-1, b}$ reads
  \begin{equation}
  \frac{(k+2n-3)!}{n!(k+n-3)!}\frac{n(n+1)}{2}.
  \end{equation}
  Since the dimension of $R(K)$ is $\frac{n(n+1)}{2}$, the dimension of $R^\perp(K)$ (with respect to $P_{k+n-2}(K;  \mathbb{R}^n)$) is
  \begin{equation}
  n\frac{(k+2n-2)!}{n!(k+n-2)!}-\frac{n(n+1)}{2}.
  \end{equation}
  It follows from the definition of $P_k^\ast(K; \mathbb{S})$ and Lemma \ref{lemma2.2} that $M_k(K)$ contains all divergence free  tensor-value functions of  $\Sigma_{K, k+n-1, b}$. Then the desired result follows from Lemma \ref{lemma2.3}.

We first  prove the first part of the theorem. It suffices to show that, given $K\in \mathcal{T}_h$, assume    the following degrees of freedom vanish  for $\tau\in P_k(K, \mathbb{S})$ with $2\leq k\leq n-1$, then $\tau\nu=0$ on
  $\partial K$ where $\nu$ is the   normal vector of $\partial K$.
\begin{itemize}
 \item For each $\ell$ dimensional simplex $\triangle_\ell$ of $K$, $0\leq \ell\leq n-2$,  with $\ell$ linearly independent tangential vectors $\b t_1, \cdots, \b t_\ell$, and $n-\ell$ linearly  independent normal vectors $\b \nu_1, \cdots, \b \nu_{n-\ell}$, the mean moments of degree at most $n-\ell$ over $\triangle_\ell$, of~~ $\b t_l^T\tau \b \nu_i$, $\b \nu_i^T\tau\b \nu_j$, $l=1, \cdots, \ell$, $i,j=1, \cdots, n-\ell$,  $\big( C_{n+1-\ell}^2+\ell (n-\ell)\big) C_{n}^\ell=\frac{(n-\ell)(n+\ell+1)}{2}C_{n}^\ell$ degrees of freedom  for each $\triangle_\ell$;
 \end{itemize}
 In fact, it follows from \cite[Theorem 2.1]{Hu2014} that such a set of degrees of freedom indicates the $\tau\nu=0$ on
  $\partial K$.

  Next we turn to the second part of the theorem.  For this case, if the above set of degrees of freedom
  and  the following set of degrees of  freedom
   \begin{itemize}
   \item  the  average moment of  degree zero of $\tau \nu$ for any $n-1$ dimensional simplex $\triangle_{n-1}$ of $K$ with the   normal vector
   \end{itemize}
    vanish,  we have $\tau\nu=0$ on $\partial K$, see \cite[Theorem 2.1]{Hu2014} for more details.  This completes the proof.

Let $v_h\in V_{k,h}$.
  By the stability of the continuous formulation,
      cf. \cite{Arnold-Winther-conforming} for two dimensional case, there is
    a $\tau \in  H^1(\Omega; \mathbb{S})$ such that,
   \a{ \d\tau=v_h \quad \hbox{\rm
      and } \quad \|\tau\|_{1}\le  C\|v_h\|_{0}. }
In this paper, we only consider the domain such that the above stability holds. We refer interested authors
    to \cite{GiraultRaviart1986} for the  classical result which states  it  is true for Lipschitz domains in
     $\mathbb{R}^n$; see \cite{Duran2001} for more refined results.
First let $I_h$ be a  Scott-Zhang \cite{Scott-Zhang}
   interpolation operator such that
  \begin{equation}\label{eq3.9}
  \|\tau-I_h\tau\|_0+h\|\nabla I_h\tau\|_0\leq Ch\|\nabla\tau\|_0.
  \end{equation}
   These enriched bubble  functions in $\sum\limits_{F}\mathbb{B}_F^1$  on the $n-1$ dimensional simplices $F$ allow for defining a correction $\delta_h\in \sum\limits_{F}\mathbb{B}_F^1$ such that
    \begin{equation}
    \int_{F} \delta_h\nu \cdot p d \b s=\int_{F} (\tau-I_h\tau)\nu\cdot p d\b s\text{ for any }
    p\in R(K)|_{F}.
    \end{equation}
    Finally we take
    \begin{equation}
    \tau_h=I_h\tau+\delta_h.
    \end{equation}
    We get  a partial-divergence matching property of $\tau_h$:
     for any $p\in R(K)$,  as the symmetric gradient $\epsilon( p)=0$,
 \a{  \int_K (\d\tau_h-v_h) \cdot p \, d\b x
     & = \int_K (\d\tau_h-\d \tau) \cdot p \, d\b x\\
        & = \int_{\partial K}  (\tau_h-\tau)\nu\cdot p\,  d\b s =0.}
 The  stability estimate follows from \eqref{eq3.9} and  the definition of the correction $\delta_h$.

The  K-ellipticity immediately follows from the fact
      that $\d  \Sigma_{k,h}^+ \subset V_{k,h}$.
      To prove the  discrete B-B  condition \meqref{inf-sup},
      for any $v_h\in V_{k,h}$,
        it follows from Lemma \ref{lemma1} and Remark \ref{remark4.1}  that there exists a
      $\tau_{1}\in \Sigma_{k,h}^+$ such that,  for any polynomial $p\in R(K)$,
   \begin{equation}  \int_K (\d\tau_1-v_h) \cdot pd\b x=0
      \quad \hbox{\rm
      and } \quad \|\tau_1\|_{H(\d)}\leq C\|v_h\|_{0}. \end{equation}

Then it follows from  Lemma  \ref{lemma2.3} that
 there is a $\tau_2\in\Sigma_{k, h}$ such that  $\tau_2|_K \in \Sigma_{K, k, b}$  and
   \begin{equation}
     \d\tau_2 = v_h-\d\tau_1, \|\tau_2\|_0=\min\{\|\tau\|_0, \d\tau=v_h-\d\tau_1, \tau\in \Sigma_{K, k, b} \}
     \end{equation}
     It follows from the definition of $\tau_2$ that $\|\d \tau_2\|_0$  defines a norm for it. Then, a scaling argument proves
\begin{equation}
 \|\tau_2 \|_{H(\d)}\leq C\|\d\tau_1-v_h\|_{0}.
\end{equation}
Let $\tau=\tau_1+\tau_2$.  This implies that
\begin{equation}
\d\tau=v_h \text{ and } \|\tau\|_{H(\d)}\leq C\|v_h\|_{0},
\end{equation}
this proves the discrete B-B condition \meqref{inf-sup}.

The stability of the elements and the standard theory of mixed
  finite element methods \cite{Brezzi, Brezzi-Fortin} give the
  following quasioptimal error estimate immediately
\an{
  \label{theorem-err1} \|\sigma-\sigma_h\|_{H({\rm
  div})}+\|u-u_h\|_{0}\leq C \inf\limits_{\tau_h\in\Sigma_{k,h}^+,v_h\in
  V_{k,h}}\left(\|\sigma-\tau_h\|_{H({\rm div})}+\|u-v_h\|_{0}\right).}
Let $P_h$ denote the local $L^2$ projection operator,
   or  element-wise interpolation operator,  from $V$ to $V_{k,h}$,
  satisfying the error estimate
\an{\label{proj-error}
   \|v-P_hv\|_{0}\leq Ch^k\|v\|_{k} \text{ for any }v\in H^k(\Omega; \mathbb{R}^n). }
Choosing $\tau_h=I_h\sigma\in \Sigma_{k,h}$
    where $I_h$ is defined in \eqref{eq3.9} as $I_h$ preserves symmetric $P_k$ functions locally,
   \an{ \lab{p-err2}
       \|\sigma -\tau_h\|_{0} + h |\sigma -\tau_h|_{H(\d)}
        \le Ch^{k+1} \|\sigma\|_{k+1}. }
 Let $v_h= P_h v$ and $\tau_h=I_h\sigma$ in (\ref{theorem-err1}),
  by (\ref{proj-error}) and \meqref{p-err2}, we
   obtain  \meqref{t1}.

remark.raw:
For $n=2$, we  recover the  lowest order element in \cite{Arnold-Winther-conforming};
 for $n=3$ we obtain the lowest order element
  in \cite{Adams-Cockburn}, see also \cite{Arnold-Awanou-Winther}.

items.raw:
Here the symmetric tensor space for the stress $\Sigma$ is  defined by
  \an{   \lab{S}
  H({\rm div},\Omega; \mathbb {S})
    &:= \Big\{ \tau=\p{\tau_{11} &\cdots &\tau_{1n} \\
        \vdots  & \vdots & \vdots \\
        \tau_{n1} &\cdots   & \tau_{nn}  }
     \in H(\d, \Omega; \mathbb{R}^{n\times n})
    \ \Big| \ \tau ^T = \tau  \Big\},}
and  the   space for the vector displacement  $V$ is
  \an{  \lab{V}
     L^2(\Omega; \mathbb{R}^n) &:=
     \Big\{ \p{u_1, &\cdots, &u_n}^T
          \ \Big| \ u_i \in L^2(\Omega), i=1, \cdots, n \Big\}  .

we define the following enriched stress space
 \begin{equation}
   \Sigma_{k, h}^+=\Sigma_{k, h}+\sum\limits_{F} \mathbb{B}_F^1 \text{ for }2\leq k\leq n-1;
 \end{equation}
 and
 \begin{equation}
  \lab{Sh-plus}
   \Sigma_{k, h}^+=\Sigma_{k, h}+\sum\limits_{F} \mathbb{B}_F^2 \text{ for }k=n.

\begin{equation}\label{Tnew}
 T_{i,j}:=\b t_{i,j}\b t_{i,j}^T,  0\leq i< j\leq n.
 \end{equation}

\begin{equation}
\Sigma_{\partial K,  k, 0}:=\{\tau\in H(\d, K;  \mathbb{S})\cap P_{k}(K; \mathbb{S}), \tau\b \nu|_{\partial K}=0 \}.
\end{equation}

\begin{equation}\label{R}
  R(K):=\{ v\in H^1(K; \mathbb{R}^n), (\nabla v+\nabla v^T)/2=0\}.
  \end{equation}

\begin{equation}\label{2Drigid}
R(K):=\bigg\{\begin{pmatrix} a_1 \\a_2 \end{pmatrix}+ b\begin{pmatrix}-x_2\\ x_1\end{pmatrix}, a_1, a_2, b\in \mathbb{R}\bigg\};
\end{equation}

\begin{equation}
 R^\perp(K):=\{v\in P_{k-1}(K; \mathbb{R}^n), (v, w)_K=0\text{ for any }w\in R(K)\},
 \end{equation}

\begin{equation}
 \Sigma_{3\rightarrow n+1, DF}(K; \mathbb{S}):=\{\tau\in P_{n+1}(K; \mathbb{S})\backslash P_2(K; \mathbb{S}), \d \tau=0 \}.
 \end{equation}

\begin{equation}
  P_2^\ast(K; \mathbb{S}):=P_2(K; \mathbb{S})+\Sigma_{3\rightarrow n+1, DF}(K; \mathbb{S}).
  \end{equation}

\begin{equation}
    M_2(K):=\{\tau\in P_2^\ast(K;  \mathbb{S}), \d\tau=0 \text{ and }\tau\nu|_{\partial K}=0 \},
  \end{equation}

\begin{equation}\label{Shplus}
\Sigma_{2,h}^\ast:=\{\tau\in H(\d, \Omega; \mathbb{S}), \tau|_K\in P_2^\ast(K; \mathbb{S}) \text{ for  any }K\in\mathcal{T}_h\}.
\end{equation}

\begin{equation}
  \hat{P}_2^\ast(K; \mathbb{S}):=\{\tau\in P_2^\ast(K; \mathbb{S}), \d\tau\in R(K)\}.
  \end{equation}

\begin{equation}\label{hatShplus}
\hat{\Sigma}_{2,h}^\ast:=\{\tau\in H(\d, \Omega; \mathbb{S}), \tau|_K\in \hat{P}_2^\ast(K; \mathbb{S}) \text{ for  any }K\in\mathcal{T}_h\}.
\end{equation}

\begin{equation}
 \Sigma_{k+1\rightarrow k+n-1, DF}(K; \mathbb{S}):=\{\tau\in P_{k+n-1}(K; \mathbb{S})\backslash P_k(K; \mathbb{S}), \d \tau=0 \}.
 \end{equation}

\begin{equation}
  P_k^\ast(K; \mathbb{S}):=P_k(K; \mathbb{S})+\Sigma_{k+1\rightarrow k+n-1, DF}(K; \mathbb{S}).
  \end{equation}

\begin{equation}
    M_k(K):=\{\tau\in P_k^\ast(K;  \mathbb{S}), \d\tau=0 \text{ and }\tau\nu|_{\partial K}=0 \},
  \end{equation}

\begin{equation}\label{Shplushorder}
\Sigma_{k,h}^\ast:=\{\tau\in H(\d, \Omega; \mathbb{S}), \tau|_K\in P_k^\ast(K; \mathbb{S}) \text{ for  any }K\in\mathcal{T}_h\}.
\end{equation}

\begin{equation}
\begin{split}
 \mathbb{B}_F^1:=&\bigg\{\tau\in \Sigma_{2,h}^\ast, \tau=0 \text{ on }\Omega\backslash\omega_F, \int_F \tau\nu\cdot p ds=0 \text{ for any } p\in \big(R(\omega_F)|_F\big)^\perp,\\
 & \text{ the averages of }\tau \text{ over both } K^- \text{ and } K^+ \text{ vanish },\\
 & \text{ the values of } \int_K\tau:\theta d\b x \text{ vanish for any }\theta\in M_2(K), K=K^- \text{ and } K^+ \bigg\}.
\end{split}
\end{equation}

\begin{equation}
 \mathbb{B}_F^2:=\{\tau\in \mathbb{B}_F^1, \int_F\tau\nu\cdot p d s=0 \text{ for any }p\in P_0(F, \mathbb{R}^n)\}.
 \end{equation}

\begin{equation}
 \Sigma_{1,h}:=\{\tau\in H^1(\Omega;  \mathbb{S}), \tau|_K\in P_1(K, \mathbb{S})\text{ for any }K\in\mathcal{T}_h\}.
 \end{equation}

\begin{equation}
\begin{split}
 \hat{\mathbb{B}}_F:=&\bigg\{\tau\in \hat{\Sigma}_{2,h}^\ast, \tau=0 \text{ on }\Omega\backslash\omega_F, \int_F \tau\nu\cdot p ds=0 \text{ for any } p\in \big(R(\omega_F)|_F\big)^\perp,\\
 & \text{ the values of } \int_K\tau:\theta d\b x \text{ vanish for any }\theta\in M_2(K), K=K^- \text{ and } K^+ \bigg\}.
\end{split}
\end{equation}

\begin{equation}
\Sigma_{F, b}:=\text{span}\{\varphi_{i, F}T_{j, F}^\perp, i, j=1, 2, 3\}.
 \end{equation}

define a $H(\d,K;  {\mathbb S})$ bubble function space
\an{\lab{bh}  \Sigma_{K, k,  b}: = \sum\limits_{0\leq i<j\leq n} \lambda_i\lambda_jP_{k-2}(K;  \mathbb{R})T_{i, j}}
Define the full $H(\d,K;  {\mathbb S})$ bubble function space consisting of polynomials of degree $\leq k$
\begin{equation}
\Sigma_{\partial K,  k, 0}:=\{\tau\in H(\d, K;  \mathbb{S})\cap P_{k}(K; \mathbb{S}), \tau\b \nu|_{\partial K}=0 \}.

Define $T^\perp_{j, F}, j=1, 2, 3$  such that
 \begin{equation}
 T_{i,F}:T_{j, F}^\perp=0,  T^\perp_{j, F}:T^\perp_{l, F}=\delta_{jl},  i, j, l=1, 2, 3.

Here the symmetric tensor space for the stress $\Sigma$ is  defined by
  \an{   \lab{S}
  H({\rm div},\Omega; \mathbb {S})
    &:= \Big\{ \tau=\p{\tau_{11} &\cdots &\tau_{1n} \\
        \vdots  & \vdots & \vdots \\
