With these symmetric matrices $T_{i,j}$ of rank one,  we define a $H(\d,K;  {\mathbb S})$ bubble function space
\an{\lab{bh}  \Sigma_{K, k,  b}: = \sum\limits_{0\leq i<j\leq n} \lambda_i\lambda_jP_{k-2}(K;  \mathbb{R})T_{i, j}}
Define the full $H(\d,K;  {\mathbb S})$ bubble function space consisting of polynomials of degree $\leq k$
\begin{equation}
\Sigma_{\partial K,  k, 0}:=\{\tau\in H(\d, K;  \mathbb{S})\cap P_{k}(K; \mathbb{S}), \tau\b \nu|_{\partial K}=0 \}.
\end{equation}
Here $\nu$ is the   normal vector of $\partial K$.

 We have the following  result  due to \cite{Hu2014}.

We need  an important result concerning the divergence space of the bubble function space.
 To this end, we introduce the following rigid motion space on each element $K$.
  \begin{equation}\label{R}
  R(K):=\{ v\in H^1(K; \mathbb{R}^n), (\nabla v+\nabla v^T)/2=0\}.
  \end{equation}
It follows from the definition that  $R(K)$ is a subspace of $P_1(K;  \mathbb{R}^n)$.
For $n=1$, $R(K)$ is the constant function space over $K$. The dimension of $R(K)$ is $\frac{n(n+1)}{2}$.
For two dimensions, the rigid motion space $R(K)$ is
\begin{equation}\label{2Drigid}
R(K):=\bigg\{\begin{pmatrix} a_1 \\a_2 \end{pmatrix}+ b\begin{pmatrix}-x_2\\ x_1\end{pmatrix}, a_1, a_2, b\in \mathbb{R}\bigg\};
\end{equation}
for three dimensions, the rigid motion space $R(K)$ reads
\begin{equation}\label{3Drigid}
R(K): =\bigg\{\begin{pmatrix} a_1 \\a_2  \\ a_3\end{pmatrix}+ b_1\begin{pmatrix}-x_2\\ x_1\\0\end{pmatrix}+b_2\begin{pmatrix}-x_3\\ 0\\x_1\end{pmatrix}+b_3\begin{pmatrix}0\\ -x_3\\x_2\end{pmatrix}, a_i, b_i\in \mathbb{R},  i=1,2,3 \bigg\}.
\end{equation}
This allows for defining the orthogonal complement  space of  $R(K)$ with  respect to $P_{k-1}(K; \mathbb{R}^n)$ by
 \begin{equation}
 R^\perp(K):=\{v\in P_{k-1}(K; \mathbb{R}^n), (v, w)_K=0\text{ for any }w\in R(K)\},
 \end{equation}
 where the inner product $(v, w)_K$ over $K$ reads $(v, w)_K=\int_K v\cdot w d\b x$.

\begin{proof} The dimension of the space $\Sigma_{K, n+1, b}$ reads
  \begin{equation}
  \frac{(2n-1)!}{n!(n-1)!}\frac{n(n+1)}{2}.
  \end{equation}
  Since the dimension of $R(K)$ is $\frac{n(n+1)}{2}$, the dimension of $R^\perp(K)$ (with respect to $P_{n}(K, \mathbb{R}^n)$) is
  \begin{equation}
  n\frac{(2n)!}{n!n!}-\frac{n(n+1)}{2}.
  \end{equation}
  It follows from the definition of $P_2^\ast(K; \mathbb{S})$ and Lemma \ref{lemma2.2} that $M_2(K)$ contains all divergence free  tensor-value functions of  $\Sigma_{K, n+1, b}$. Then the desired result follows from Lemma \ref{lemma2.3}.
  \end{proof}

\begin{proof} We assume that all degrees of freedom vanish and show that $\tau=0$. Note that the mean moment becomes the value of $\tau$ for a $0$ dimensional simplex $\triangle_0$, namely, a vertex, of $K$.  The  first set of degrees of freedom implies that $\tau \b \nu =0$ on $\partial K$ while the second set of degrees of freedom shows $\d \tau=0$. Then the third set of
 degrees of freedom  proves that $\tau=0$. Next we shall
 prove that the sum of these  degrees of freedom is equal to the dimension of the space $P_2^\ast(K, \mathbb{S})$. In fact
  the sum of the first set of degrees of freedom is
  \begin{equation*}
  \sum\limits_{\ell=0}^{n-1}C_{n+1}^{\ell+1}\frac{(n-\ell)(n+\ell+1)}{2}C_{n}^\ell,
  \end{equation*}
  we refer interested readers to \cite[Theorem 2.1]{Hu2014} for a detailed proof of the numbers of degrees of freedom in the first set.
  By the Chu-Vandermonde combinatorial identity \eqref{van} and its variant \eqref{varvan}, see more details from \cite{Hu2014},
  \begin{equation*}
  \sum\limits_{\ell=0}^{n-1}C_{n+1}^{\ell+1}\frac{(n-\ell)(n+\ell+1)}{2}C_{n}^\ell=\frac{(2n+1)!}{n!(n+1)!}\frac{n(n+1)}{2}-
  \frac{(2n-1)!}{n!(n-1)!}\frac{n(n+1)}{2}.
  \end{equation*}
  Hence the  desired result follows from \eqref{eq3.4}, and the sum of the second and third sets of degrees of freedom.
\end{proof}

Then we define
\begin{equation}\label{Shplus}
\Sigma_{2,h}^\ast:=\{\tau\in H(\d, \Omega; \mathbb{S}), \tau|_K\in P_2^\ast(K; \mathbb{S}) \text{ for  any }K\in\mathcal{T}_h\}.
\end{equation}

\begin{remark} For $n=2$, we  recover the  lowest order element in \cite{Arnold-Winther-conforming};
